import { act, renderHook } from "@testing-library/react";
import { useController } from "react-hook-form";
import { describe, it, expect, vi } from "vitest";

import type { ChildrenEventType } from "@calcom/features/eventtypes/lib/childrenEventType";
import { stripChildrenForPayload } from "@calcom/features/eventtypes/lib/childrenEventType";
import type { EventTypeSetupProps } from "@calcom/features/eventtypes/lib/types";
import { MembershipRole, RescheduleReasonRequirement } from "@calcom/prisma/enums";

import { useEventTypeForm } from "./useEventTypeForm";

vi.mock("@calcom/lib/hooks/useLocale", () => ({
  useLocale: () => ({ t: (key: string) => key }),
}));

describe("useEventTypeForm - children payload stripping", () => {
  it("should strip avatar, profile, username, and membership from children payload", () => {
    const children: ChildrenEventType[] = [
      {
        value: "1",
        label: "Alice",
        created: true,
        slug: "test-event",
        hidden: false,
        owner: {
          id: 1,
          name: "Alice",
          email: "alice@example.com",
          username: "alice",
          avatar: "data:image/png;base64," + "A".repeat(50000), // Large base64 avatar
          membership: MembershipRole.MEMBER,
          eventTypeSlugs: ["meeting", "consultation"],
          profile: {
            id: 1,
            username: "alice",
            upId: "usr_1",
            organizationId: null,
            organization: null,
          },
        },
      },
      {
        value: "2",
        label: "Bob",
        created: false,
        slug: "test-event",
        hidden: true,
        owner: {
          id: 2,
          name: "Bob",
          email: "bob@example.com",
          username: "bob",
          avatar: "https://example.com/avatars/bob.png",
          membership: MembershipRole.OWNER,
          eventTypeSlugs: [],
          profile: {
            id: 2,
            username: "bob",
            upId: "usr_2",
            organizationId: 10,
            organization: {
              id: 10,
              slug: "org",
              name: "Org",
              calVideoLogo: null,
              bannerUrl: "",
              isPlatform: false,
            },
          },
        },
      },
    ];

    const stripped = stripChildrenForPayload(children);

    // Should only contain server-needed fields
    expect(stripped).toEqual([
      {
        hidden: false,
        owner: {
          id: 1,
          name: "Alice",
          email: "alice@example.com",
          eventTypeSlugs: ["meeting", "consultation"],
        },
      },
      {
        hidden: true,
        owner: {
          id: 2,
          name: "Bob",
          email: "bob@example.com",
          eventTypeSlugs: [],
        },
      },
    ]);

    // Verify avatar is not present
    for (const child of stripped) {
      expect(child.owner).not.toHaveProperty("avatar");
      expect(child.owner).not.toHaveProperty("profile");
      expect(child.owner).not.toHaveProperty("username");
      expect(child.owner).not.toHaveProperty("membership");
    }
  });

  it("should significantly reduce payload size for large teams", () => {
    // Simulate 85 users with base64 avatars (~10KB each)
    const largeBase64Avatar = "data:image/png;base64," + "A".repeat(10000);

    const children: ChildrenEventType[] = Array.from({ length: 85 }, (_, i) => ({
      value: String(i + 1),
      label: `User ${i + 1}`,
      created: true,
      slug: "managed-event",
      hidden: false,
      owner: {
        id: i + 1,
        name: `User ${i + 1}`,
        email: `user${i + 1}@example.com`,
        username: `user${i + 1}`,
        avatar: largeBase64Avatar,
        membership: MembershipRole.MEMBER,
        eventTypeSlugs: ["event-a", "event-b"],
        profile: {
          id: i + 1,
          username: `user${i + 1}`,
          upId: `usr_${i + 1}`,
          organizationId: 1,
          organization: {
            id: 1,
            slug: "org",
            name: "Large Org",
            calVideoLogo: null,
            bannerUrl: "",
            isPlatform: false,
          },
        },
      },
    }));

    const fullPayloadSize = JSON.stringify(children).length;
    const strippedPayloadSize = JSON.stringify(stripChildrenForPayload(children)).length;

    // The stripped payload should be dramatically smaller
    expect(strippedPayloadSize).toBeLessThan(fullPayloadSize * 0.1);

    // Full payload with 85 users and 10KB avatars should be around 850KB+
    expect(fullPayloadSize).toBeGreaterThan(800000);

    // Stripped payload should be well under 1MB
    expect(strippedPayloadSize).toBeLessThan(100000);
  });

  it("should handle undefined children gracefully", () => {
    const children: ChildrenEventType[] = [];
    const stripped = stripChildrenForPayload(children);
    expect(stripped).toEqual([]);
  });
});

const eventTypeWithRescheduleReason = (
  requiresRescheduleReason: RescheduleReasonRequirement | null | undefined
) =>
  ({
    id: 1,
    title: "Test Event",
    slug: "test-event",
    metadata: {},
    hashedLink: [],
    hosts: [],
    children: [],
    team: null,
    requiresCancellationReason: null,
    requiresRescheduleReason,
  }) as unknown as EventTypeSetupProps["eventType"];

describe("useEventTypeForm - reschedule reason requirement", () => {
  it.each([
    [RescheduleReasonRequirement.MANDATORY_HOST_ONLY, RescheduleReasonRequirement.MANDATORY_HOST_ONLY],
    [null, null],
    [undefined, null],
  ])("loads a stored value of %s into the form as %s", (stored, expected) => {
    const { result } = renderHook(() =>
      useEventTypeForm({ eventType: eventTypeWithRescheduleReason(stored), onSubmit: vi.fn() })
    );

    expect(result.current.form.getValues("requiresRescheduleReason")).toBe(expected);
  });

  it("keeps the form unchanged when the dropdown mounts after the form and an edit is reverted", () => {
    const { result: editor } = renderHook(() =>
      useEventTypeForm({
        eventType: eventTypeWithRescheduleReason(RescheduleReasonRequirement.OPTIONAL_BOTH),
        onSubmit: vi.fn(),
      })
    );

    // The editor renders one tab at a time, so the Advanced tab's dropdown always registers after the
    // form exists. If the field were missing from the form's defaults, registering it would mark the
    // whole form as changed, enabling Save and the unsaved-changes dialog without any edit.
    const { result: dropdown } = renderHook(() =>
      useController({
        name: "requiresRescheduleReason",
        control: editor.current.form.control,
        defaultValue: RescheduleReasonRequirement.OPTIONAL_BOTH,
      })
    );
    expect(editor.current.form.formState.isDirty).toBe(false);

    act(() => {
      dropdown.current.field.onChange(RescheduleReasonRequirement.MANDATORY_BOTH);
    });
    expect(editor.current.form.formState.isDirty).toBe(true);

    act(() => {
      dropdown.current.field.onChange(RescheduleReasonRequirement.OPTIONAL_BOTH);
    });
    expect(editor.current.form.formState.isDirty).toBe(false);
  });
});

const eventTypeWithCancellationNotice = (minimumCancellationNotice: number | null | undefined) =>
  ({
    id: 1,
    title: "Test Event",
    slug: "test-event",
    metadata: {},
    hashedLink: [],
    hosts: [],
    children: [],
    team: null,
    requiresCancellationReason: null,
    minimumCancellationNotice,
  }) as unknown as EventTypeSetupProps["eventType"];

describe("useEventTypeForm - minimum cancellation notice", () => {
  it.each([
    [1440, 1440],
    [null, null],
    [undefined, null],
  ])("loads a stored value of %s into the form as %s", (stored, expected) => {
    const { result } = renderHook(() =>
      useEventTypeForm({ eventType: eventTypeWithCancellationNotice(stored), onSubmit: vi.fn() })
    );

    expect(result.current.form.getValues("minimumCancellationNotice")).toBe(expected);
  });

  it.each([
    ["saves a newly set notice", null, 1440],
    ["clears the notice when the setting is turned off", 1440, null],
  ])("%s", (_label, stored, edited) => {
    const onSubmit = vi.fn();
    const { result } = renderHook(() =>
      useEventTypeForm({ eventType: eventTypeWithCancellationNotice(stored), onSubmit })
    );

    act(() => {
      result.current.form.setValue("minimumCancellationNotice", edited, { shouldDirty: true });
    });
    act(() => {
      result.current.handleSubmit(result.current.form.getValues());
    });

    expect(onSubmit).toHaveBeenCalledWith(
      expect.objectContaining({ id: 1, minimumCancellationNotice: edited })
    );
  });

  it("does not send the notice when it was not changed", () => {
    const onSubmit = vi.fn();
    const { result } = renderHook(() =>
      useEventTypeForm({ eventType: eventTypeWithCancellationNotice(1440), onSubmit })
    );

    act(() => {
      result.current.form.setValue("title", "Renamed", { shouldDirty: true });
    });
    act(() => {
      result.current.handleSubmit(result.current.form.getValues());
    });

    expect(onSubmit).toHaveBeenCalledTimes(1);
    expect(onSubmit.mock.calls[0][0]).not.toHaveProperty("minimumCancellationNotice");
  });
});

