      responses: {},
      references: [],
      attendees: [
        {
          id: 1,
          name: "John Doe",
          email: "john@example.com",
          timeZone: "America/New_York",
          phoneNumber: null,
          locale: "en",
          bookingId: 1,
          noShow: false,
